function renderPortfolio(){const visible=state.showAll?projects:projects.slice(0,24);$('#portfolio-grid').innerHTML=visible.map(p=>`<button class="project-card lift reveal" data-project="${p.title}" type="button"><div class="project-image-wrap ${colorClass(p.color.replace('bg-',''))}"><img class="project-image" src="assets/${projectImg[p.src]}" alt="${p.title} brand identity project" loading="lazy"></div><div class="project-body"><div class="project-top"><span class="project-title">${p.title}</span><span class="project-year">${p.year}</span></div><div class="project-bottom" style="margin-top:8px"><span class="tag ${colorClass(p.color.replace('bg-',''))}">${p.type}</span><span class="view">View details →</span></div></div></button>`).join('');$('#more-projects').textContent=state.showAll?'Show less':`More projects (${projects.length-24})`}
function typeIcon(name){const icons={"Letter Mark":"A","Wordmark":"W","Typography Logo":"T","Combination Mark":"◇","Abstract Mark":"◒","Mascot Logo":"★","Emblem Logo":"⬡","Minimalist Logo":"○"};return `<span class="type-icon ${colorClass(logoTypes.find(x=>x[0]===name)?.[2]||'sky')}">${icons[name]||'◌'}</span>`}
function renderTypes(){ $('#type-grid').innerHTML=logoTypes.map(x=>`<button type="button" class="type-card lift ${state.logoType===x[0]?'selected':''}" data-type="${x[0]}">${typeIcon(x[0])}<span class="type-name">${x[0]}</span><span class="type-copy">${x[1]}</span><span class="pick-label">Pick this type →</span></button>`).join('') }
function renderPackages(){ $('#package-grid').innerHTML=packages.map(p=>`<article class="package-card lift ${p.featured?'featured':''}">${p.featured?'<span class="popular">Most popular</span>':''}<div class="pkg-top"><h4 class="pkg-name">${p.name}</h4><span class="pkg-price">${p.price}</span></div><p class="pkg-time">${p.time}</p><ul>${p.items.map(it=>`<li><span class="check">✓</span><span>${it}</span></li>`).join('')}</ul><button type="button" class="package-btn" data-pkg="${p.name}">Choose ${p.name}</button></article>`).join('') }
function renderRefs(){ $('#refs').innerHTML=state.refs.map((r,i)=>`<div class="ref-row"><label class="field">Reference link ${i+1}<input type="url" data-ref-url="${i}" value="${esc(r.url)}" placeholder="https://…"></label><label class="field">Why you like it<input data-ref-note="${i}" value="${esc(r.note)}" maxlength="160" placeholder="Clean type, bold colours…"></label><button type="button" class="remove-ref" data-remove-ref="${i}" aria-label="Remove reference">×</button></div>`).join('') }
function renderOrderForm(){
 const options=(arr)=>arr.map(v=>`<option>${v}</option>`).join('');
 $('#order-form').innerHTML=`<label class="field">Your name<input name="name" required maxlength="80" placeholder="Jane Doe"></label><label class="field">Email<input name="email" required type="email" maxlength="160" placeholder="jane@brand.com"></label><label class="field">Phone<input name="phone" type="tel" maxlength="30" placeholder="+880 1700 000000"></label><label class="field">WhatsApp number<input name="whatsapp" type="tel" maxlength="30" placeholder="+880 1700 000000"></label><label class="field">Company / organisation<input name="company" maxlength="120" placeholder="Northwind Ltd."></label><label class="field">Brand name on the logo<input name="brand" required maxlength="120" placeholder="Northwind"></label><label class="field">Industry<input name="industry" maxlength="120" placeholder="Coffee, SaaS, fashion…"></label><label class="field">Slogan / tagline<input name="slogan" maxlength="120" placeholder="Brewed for the bold"></label><label class="field">Logo type<select name="logoType">${options(logoTypes.map(x=>x[0]))}</select></label><label class="field">Package<select name="pkg">${options(packages.map(x=>x.name))}</select></label><label class="field">Budget<select name="budget">${options(['Under $100','$100 – $250','$250 – $500','$500 – $1000','$1000+'])}</select></label><label class="field">Deadline<input name="deadline" type="date"></label><label class="field">Revisions needed<select name="revisions">${options(['2','4','6','Unlimited'])}</select></label><label class="field">Payment method<select name="payment">${options(['bKash','Nagad','Rocket','Bank transfer','PayPal','Wise','Payoneer'])}</select></label><label class="field">Colour preference<input name="colors" placeholder="#6633CC, blue, warm neutrals…"></label><label class="field">Font preference<input name="fonts" placeholder="Geometric sans, elegant serif…"></label><label class="field full">Competitors / brands to stand apart from<input name="competitors" placeholder="competitor1.com, competitor2.com"></label><fieldset class="full" style="border:0;padding:0;margin:0"><legend class="field">Style direction</legend><div class="select-pills" id="style-pills">${['Minimal','Bold','Playful','Luxury','Retro','Corporate','Handmade','Techy'].map(x=>`<button type="button" class="select-pill ${state.styles.includes(x)?'active':''}" data-style="${x}">${x}</button>`).join('')}</div></fieldset><fieldset class="full" style="border:0;padding:0;margin:0"><legend class="field">Delivery formats</legend><div class="select-pills" id="format-pills">${['PNG','JPG','SVG','PDF','AI','EPS','Favicon','MP4 animation'].map(x=>`<button type="button" class="select-pill ${state.formats.includes(x)?'active coral-active':''}" data-format="${x}">${x}</button>`).join('')}</div></fieldset><fieldset class="full" style="border:0;padding:0;margin:0"><legend class="field">Add-ons</legend><div class="select-pills" id="addon-pills">${addons.map(x=>{const v=x[0]+' '+x[1];return `<button type="button" class="select-pill ${state.addons.includes(v)?'active sun-active':''}" data-addon="${esc(v)}">${x[0]} <strong>${x[1]}</strong></button>`}).join('')}</div></fieldset><label class="field full">Project details<textarea name="details" maxlength="2000" rows="5" placeholder="Your story, audience, where the logo will be used, what to avoid…"></textarea></label><div class="full"><button type="submit" class="btn-primary">◉ Place order — send to WhatsApp &amp; email</button><p class="help">Your brief is delivered straight to ${SITE.phoneDisplay} on WhatsApp and to ${SITE.emailPrimary}. You get an order ID and a downloadable payment receipt instantly.</p></div>`;
 $('#order-form [name="logoType"]').value=state.logoType;$('#order-form [name="pkg"]').value=state.pkg;
}
function renderMessageForm(){ $('#message-form').innerHTML=`<label class="field">Name<input name="name" maxlength="80" placeholder="Your name"><span class="error" data-error="name"></span></label><div class="grid-2" style="gap:12px"><label class="field">Email<input name="email" maxlength="160" placeholder="you@brand.com"><span class="error" data-error="email"></span></label><label class="field">Phone (optional)<input name="phone" maxlength="30" placeholder="+880 …"></label></div><label class="field">Message<textarea name="message" rows="3" maxlength="1500" placeholder="Tell me about your brand and what you need…"></textarea><span class="error" data-error="message"></span></label><div class="actions" style="justify-content:flex-start;margin-top:4px"><button type="submit" class="btn-primary">✉ Send email</button><button type="button" id="msg-wa" class="btn-primary" style="background:var(--violet-block)">◉ Send on WhatsApp</button></div>` }
function bind(){
 $('#menu-btn').onclick=()=>{state.menuOpen=!state.menuOpen;render()};$$('.mobile-link').forEach(a=>a.onclick=()=>{state.menuOpen=false});
 $('#more-projects').onclick=()=>{state.showAll=!state.showAll;renderPortfolio();observeReveal()};
 $('#portfolio-grid').onclick=e=>{const b=e.target.closest('[data-project]');if(b)openProject(projects.find(p=>p.title===b.dataset.project))};
 $('#type-grid').onclick=e=>{const b=e.target.closest('[data-type]');if(!b)return;state.logoType=b.dataset.type;renderTypes();$('#order-form [name="logoType"]').value=state.logoType;$('#order-form').scrollIntoView({behavior:'smooth',block:'center'})};
 $('#package-grid').onclick=e=>{const b=e.target.closest('[data-pkg]');if(!b)return;state.pkg=b.dataset.pkg;$('#order-form [name="pkg"]').value=state.pkg;$('#order-form').scrollIntoView({behavior:'smooth',block:'center'})};
 $('#add-ref').onclick=()=>{state.refs.push({url:'',note:''});renderRefs();bindRefs()};bindRefs();
 $('#order-form').onclick=e=>{let b=e.target.closest('[data-style],[data-format],[data-addon]');if(!b)return;const key=b.dataset.style?'styles':b.dataset.format?'formats':'addons';const val=b.dataset.style||b.dataset.format||b.dataset.addon;state[key]=state[key].includes(val)?state[key].filter(x=>x!==val):[...state[key],val];renderOrderForm();bindOrderFormOnly()};
 $('#order-form').onsubmit=submitOrder; $('#message-form').onsubmit=sendMessageEmail; $('#msg-wa').onclick=sendMessageWA;
}
function bindRefs(){$$('#refs input').forEach(i=>i.oninput=()=>{const n=i.dataset.refUrl!==undefined?i.dataset.refUrl:i.dataset.refNote;const k=i.dataset.refUrl!==undefined?'url':'note';state.refs[Number(n)][k]=i.value});$$('[data-remove-ref]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.removeRef);state.refs=state.refs.length===1?[{url:'',note:''}]:state.refs.filter((_,j)=>j!==i);renderRefs();bindRefs()})}
function bindOrderFormOnly(){ $('#order-form').onclick=e=>{let b=e.target.closest('[data-style],[data-format],[data-addon]');if(!b)return;const key=b.dataset.style?'styles':b.dataset.format?'formats':'addons';const val=b.dataset.style||b.dataset.format||b.dataset.addon;state[key]=state[key].includes(val)?state[key].filter(x=>x!==val):[...state[key],val];renderOrderForm();bindOrderFormOnly()}; }
function makeOrderId(){const d=new Date().toISOString().slice(2,10).replace(/-/g,'');return `LG-${d}-${Math.floor(1000+Math.random()*9000)}`}
function orderFromForm(){const fd=new FormData($('#order-form'));const o=Object.fromEntries(fd.entries());o.logoType=state.logoType;o.pkg=state.pkg;o.styles=[...state.styles];o.formats=[...state.formats];o.addons=[...state.addons];o.references=state.refs.map(r=>({...r}));o.orderId=makeOrderId();o.price=(packages.find(p=>p.name===o.pkg)||{}).price||'On request';return o}
function orderToText(o){const line=(l,v)=>v?`${l}: ${v}\n`:'';const refs=o.references.filter(r=>r.url.trim()||r.note.trim()).map((r,i)=>`  ${i+1}. ${r.url||'(no link)'}${r.note?` — ${r.note}`:''}`).join('\n');return `NEW LOGO ORDER — ${SITE.name}\nOrder ID: ${o.orderId}\nDate: ${new Date().toLocaleString()}\n\n--- CLIENT ---\n${line('Name',o.name)}${line('Email',o.email)}${line('Phone',o.phone)}${line('WhatsApp',o.whatsapp)}${line('Company',o.company)}\n--- PROJECT ---\n${line('Brand name',o.brand)}${line('Industry',o.industry)}${line('Slogan / tagline',o.slogan)}${line('Package',o.pkg)}${line('Price',o.price)}${line('Logo type',o.logoType)}${line('Style',o.styles.join(', '))}${line('Colour preference',o.colors)}${line('Font preference',o.fonts)}${line('Competitors',o.competitors)}${line('File formats',o.formats.join(', '))}${line('Revisions',o.revisions)}${line('Add-ons',o.addons.join(', '))}${line('Budget',o.budget)}${line('Deadline',o.deadline)}${line('Payment method',o.payment)}\n--- INSPIRATION / REFERENCE LOGOS ---\n${refs||'  (none provided)'}\n\n--- BRIEF ---\n${o.details||'(none)'}\n`}
function waLink(text){const safe=text.length>1400?`${text.slice(0,1400)}\n… (full brief sent by email)`:text;return `https://wa.me/${SITE.whatsapp}?text=${encodeURIComponent(safe)}`}
function mailLink(subject,body){return `mailto:${SITE.emailPrimary}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`}
function submitOrder(e){e.preventDefault();const data=orderFromForm();state.placed=data;const text=orderToText(data);const wa=window.open(waLink(text),'_blank','noopener,noreferrer');if(!wa)toast('Pop-up blocked — use the “Send on WhatsApp” button below.');const mail=document.createElement('a');mail.href=mailLink(`Logo order ${data.orderId} — ${data.brand||data.name}`,text);document.body.appendChild(mail);mail.click();mail.remove();toast(`Order ${data.orderId} placed — sending to WhatsApp & email`);renderConfirmation();setTimeout(()=>$('#confirmation').scrollIntoView({behavior:'smooth'}),200)}
function renderConfirmation(){const o=state.placed;if(!o){$('#confirmation').innerHTML='';return}$('#confirmation').innerHTML=`<div id="order-confirmation" class="confirmation"><div class="confirm-head"><div class="confirm-icon">✓</div><div><h4 style="margin:0;font-family:'Plus Jakarta Sans';font-size:20px">Order ${o.orderId} placed</h4><p class="muted" style="margin:4px 0 0;font-size:14px;line-height:1.6">Your brief has been sent to Logoogle on WhatsApp and email. Download your receipt below and keep the order ID for payment.</p></div></div><dl class="confirm-grid"><div class="confirm-box"><dt>Package</dt><dd>${o.pkg}</dd></div><div class="confirm-box"><dt>Amount</dt><dd>${o.price}</dd></div><div class="confirm-box"><dt>Payment method</dt><dd>${o.payment}</dd></div></dl><div class="confirm-actions"><button id="download-receipt" class="btn-secondary">↓ Download money receipt</button><a class="btn-primary" target="_blank" href="${waLink(orderToText(o))}">◉ Resend on WhatsApp</a><a class="btn-secondary" href="${mailLink(`Logo order ${o.orderId}`,orderToText(o))}">✉ Resend by email</a></div><p class="help">💳 Pay with ${o.payment} to ${SITE.paymentNumber} (bKash · Nagad · Rocket) using order ID ${o.orderId} as the reference.</p></div>`;$('#download-receipt').onclick=()=>downloadReceipt(o)}
function receiptHtml(o){const now=new Date(),due=new Date(now.getTime()+3*864e5),refs=o.references.filter(r=>r.url.trim()||r.note.trim());const row=(k,v)=>`<tr><td class="k">${esc(k)}</td><td class="v">${esc(v)}</td></tr>`;return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Receipt ${esc(o.orderId)} — ${SITE.name}</title><style>:root{--v:#6633CC;--b:#3366FF;--ink:#160c2e;--g:#6b6480;--line:#ece8f6;--soft:#f7f5fb}*{box-sizing:border-box}body{margin:0;padding:32px 20px;background:var(--soft);font-family:ui-sans-serif,system-ui;color:var(--ink);-webkit-print-color-adjust:exact;print-color-adjust:exact}.sheet{max-width:820px;margin:auto;background:#fff;border-radius:22px;overflow:hidden;box-shadow:0 24px 70px -34px rgba(102,51,204,.45)}.head{background:linear-gradient(125deg,var(--v),var(--b));color:#fff;padding:32px 36px}.head-top{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap}.brand{display:flex;align-items:center;gap:14px}.glyph{width:46px;height:46px;border-radius:14px;background:rgba(255,255,255,.18);display:flex;align-items:center;justify-content:center;font-weight:800;font-size:20px}.head h1{margin:0;font-size:22px}.head .sub{margin:3px 0 0;font-size:12.5px;opacity:.85}.badge{background:rgba(255,255,255,.16);border:1px solid rgba(255,255,255,.28);border-radius:999px;padding:7px 15px;font-size:11px;font-weight:700;letter-spacing:.12em;text-transform:uppercase}.meta{margin-top:26px;display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:14px}.meta div{background:rgba(255,255,255,.12);border-radius:14px;padding:12px 14px}.meta span{display:block;font-size:10.5px;letter-spacing:.12em;text-transform:uppercase;opacity:.8}.meta strong{display:block;margin-top:5px;font-size:14.5px}.body{padding:8px 36px 0}.body section{padding:24px 0;border-bottom:1px solid var(--line)}h2{margin:0 0 14px;font-size:11.5px;letter-spacing:.16em;text-transform:uppercase;color:var(--v)}table{width:100%;border-collapse:collapse;font-size:13.5px}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:0 32px}td{padding:7px 0;vertical-align:top}td.k{color:var(--g);width:44%;font-weight:600}td.v{font-weight:600}.items th{text-align:left;font-size:10.5px;letter-spacing:.12em;text-transform:uppercase;color:var(--g);padding:0 0 10px;border-bottom:1px solid var(--line)}.items td{padding:14px 0;border-bottom:1px solid var(--line)}.desc{color:var(--g);font-size:12.5px;margin-top:3px}.amt{text-align:right;font-weight:800;white-space:nowrap}.totals{margin:16px 0 0 auto;width:100%;max-width:320px}.totals .lbl{color:var(--g);font-weight:600}.totals .val{text-align:right;font-weight:700}.grand{margin-top:14px;display:flex;justify-content:space-between;background:linear-gradient(125deg,var(--v),var(--b));color:#fff;border-radius:16px;padding:16px 20px;font-weight:800;font-size:18px}.pay{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px;margin-top:14px}.pay div{background:var(--soft);border:1px solid var(--line);border-radius:14px;padding:12px 14px}.pay span{display:block;font-size:10.5px;letter-spacing:.12em;text-transform:uppercase;color:var(--g)}.pay strong{display:block;margin-top:5px;font-size:15px}.note{font-size:13px;color:var(--g);line-height:1.7;white-space:pre-wrap}.status{display:inline-block;background:#fff3d6;color:#8a5a00;border-radius:999px;padding:5px 12px;font-size:11px;font-weight:800;text-transform:uppercase}.foot{padding:24px 36px 30px;font-size:12px;color:var(--g);line-height:1.8}a{color:var(--b);text-decoration:none}@media print{body{background:#fff;padding:0}.sheet{box-shadow:none;border-radius:0}}@media(max-width:640px){.grid2{grid-template-columns:1fr}.head,.body,.foot{padding-left:20px;padding-right:20px}}</style></head><body><div class="sheet"><div class="head"><div class="head-top"><div class="brand"><div class="glyph">Lg</div><div><h1>${SITE.name}</h1><p class="sub">Logo &amp; brand identity design · ${SITE.owner}</p></div></div><span class="badge">Order receipt / invoice</span></div><div class="meta"><div><span>Receipt no.</span><strong>${esc(o.orderId)}</strong></div><div><span>Issued</span><strong>${now.toLocaleDateString()}</strong></div><div><span>Package</span><strong>${esc(o.pkg)}</strong></div><div><span>Total</span><strong>${esc(o.price)}</strong></div></div></div><div class="body"><section><div class="grid2"><div><h2>Billed to</h2><table><tbody>${[['Name',o.name||'—'],['Company',o.company||'—'],['Email',o.email||'—'],['Phone',o.phone||'—'],['WhatsApp',o.whatsapp||o.phone||'—']].map(x=>row(...x)).join('')}</tbody></table></div><div><h2>Designer</h2><table><tbody>${[['Studio',SITE.name],['Designer',SITE.owner],['Email',SITE.emailPrimary],['WhatsApp',SITE.phoneDisplay],['Address',SITE.addressLine]].map(x=>row(...x)).join('')}</tbody></table></div></div></section><section><h2>Project brief summary</h2><div class="grid2"><table><tbody>${[['Brand name',o.brand||'—'],['Industry',o.industry||'—'],['Slogan / tagline',o.slogan||'—'],['Logo type',o.logoType]].map(x=>row(...x)).join('')}</tbody></table><table><tbody>${[['Style direction',o.styles.length?o.styles.join(', '):'—'],['Colour preference',o.colors||'—'],['Font preference',o.fonts||'—'],['Competitors',o.competitors||'—']].map(x=>row(...x)).join('')}</tbody></table></div></section><section><h2>Order summary</h2><table class="items"><thead><tr><th>Description</th><th style="text-align:right">Amount</th></tr></thead><tbody><tr><td><strong>${esc(o.pkg)} package</strong><div class="desc">${esc(o.logoType)} · ${esc(o.formats.join(', ')||'PNG, SVG')} · ${esc(o.revisions)} revision(s)</div></td><td class="amt">${esc(o.price)}</td></tr>${o.addons.length?`<tr><td><strong>Add-ons</strong><div class="desc">${esc(o.addons.join(', '))}</div></td><td class="amt">Quoted separately</td></tr>`:''}</tbody></table><table class="totals"><tbody><tr><td class="lbl">Subtotal</td><td class="val">${esc(o.price)}</td></tr><tr><td class="lbl">Discount</td><td class="val">—</td></tr><tr><td class="lbl">Tax / VAT</td><td class="val">Not applicable</td></tr></tbody></table><div class="grand"><span>Total payable</span><span>${esc(o.price)}</span></div></section><section><h2>Payment instructions</h2><p class="note">Send the total to the number below using <strong>Send Money</strong> on bKash, Nagad or Rocket, then share the transaction ID on WhatsApp with your order ID.</p><div class="pay"><div><span>bKash / Nagad / Rocket</span><strong>${SITE.paymentNumber}</strong></div><div><span>Account name</span><strong>${SITE.owner}</strong></div><div><span>Reference</span><strong>${esc(o.orderId)}</strong></div><div><span>Due date</span><strong>${due.toLocaleDateString()}</strong></div></div><table style="margin-top:14px"><tbody>${[['Deadline',o.deadline||'To be agreed'],['Payment method',o.payment],['Payment number',`${SITE.paymentNumber} (bKash · Nagad · Rocket)`],['Payment reference',o.orderId],['Payment due',due.toLocaleDateString()]].map(x=>row(...x)).join('')}</tbody></table><p style="margin-top:14px">Status: <span class="status">Payment pending</span></p></section><section><h2>Reference logos &amp; notes</h2><p class="note">${refs.length?refs.map((r,i)=>`${i+1}. ${esc(r.url||'(no link)')}${r.note?` — ${esc(r.note)}`:''}`).join('\n'):'No reference links provided.'}</p><h2 style="margin-top:20px">Client brief</h2><p class="note">${esc(o.details||'No additional notes provided.')}</p></section><section style="border-bottom:none"><h2>Terms &amp; delivery</h2><ol><li>Work begins once the advance payment is confirmed against this receipt reference.</li><li>Initial concepts are shared within 2–4 working days of confirmation.</li><li>${esc(o.revisions)} revision round(s) are included in the ${esc(o.pkg)} package.</li><li>Final files are delivered in ${esc(o.formats.join(', ')||'PNG, SVG')} after full payment.</li><li>Full copyright transfers to the client upon final payment.</li></ol></section></div><div class="foot">Thank you for choosing ${SITE.name}. Questions about this receipt? Email <a href="mailto:${SITE.emailPrimary}">${SITE.emailPrimary}</a> or WhatsApp <a href="https://wa.me/${SITE.whatsapp}">${SITE.phoneDisplay}</a>.<br>${SITE.addressLine} · ${SITE.hours}<br>This document is a computer-generated order receipt and does not require a signature.</div></div></body></html>`}
function downloadReceipt(o){const blob=new Blob([receiptHtml(o)],{type:'text/html;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${SITE.name}-receipt-${o.orderId}.html`;a.click();URL.revokeObjectURL(url)}
function sendMessageData(){const f=$('#message-form');const d=Object.fromEntries(new FormData(f).entries());const errors={};if(!String(d.name||'').trim()||String(d.name).trim().length<2)errors.name='Please enter your name';if(!/^\S+@\S+\.\S+$/.test(String(d.email||'').trim()))errors.email='Enter a valid email';if(String(d.message||'').trim().length<10)errors.message='Tell me a little more (10+ characters)';$$('.error',f).forEach(x=>x.textContent='');Object.entries(errors).forEach(([k,v])=>{const x=$(`[data-error="${k}"]`,f);if(x)x.textContent=v});if(Object.keys(errors).length){toast('Please fix the highlighted fields');return null}const text=`New message from ${SITE.name} website\n\nName: ${String(d.name).trim()}\nEmail: ${String(d.email).trim()}\n${d.phone?`Phone: ${String(d.phone).trim()}\n`:''}\nMessage:\n${String(d.message).trim()}`;return {d,text}}
function sendMessageEmail(e){e.preventDefault();const b=sendMessageData();if(!b)return;window.location.href=mailLink(`Website message — ${b.d.name}`,b.text);toast('Opening your email app with the message ready to send.')}
function sendMessageWA(){const b=sendMessageData();if(!b)return;window.open(waLink(b.text),'_blank','noopener,noreferrer');toast('Opening WhatsApp with your message.')}
function openProject(p){if(!p)return;state.active=p;document.body.style.overflow='hidden';$('#modal-root').innerHTML=`<div class="modal-backdrop" id="modal-backdrop" role="dialog" aria-modal="true" aria-label="${esc(p.title)} case study"><div class="modal"><div class="modal-hero ${colorClass(p.color.replace('bg-',''))}"><img src="assets/${projectImg[p.src]}" alt="${p.title} brand identity case study"><button class="modal-close" id="modal-close" aria-label="Close case study">×</button></div><div class="modal-body"><div class="modal-tags"><span class="tag ${colorClass(p.color.replace('bg-',''))}">${p.type}</span><span class="tag" style="background:var(--secondary);color:var(--muted-foreground)">${p.year}</span><span class="tag" style="background:var(--secondary);color:var(--muted-foreground)">${p.tag}</span></div><h3>${p.title}</h3><p class="client">Client · ${p.client}</p><p class="brief">${p.brief}</p><h4 style="margin-top:24px;font-family:'Plus Jakarta Sans';font-size:14px;text-transform:uppercase;letter-spacing:.08em">Deliverables</h4><ul class="deliverables">${p.deliverables.map(d=>`<li><span style="color:var(--coral)">✓</span> ${d}</li>`).join('')}</ul><div class="modal-actions"><a href="#order" class="btn-primary" id="modal-order">Order a ${p.type.toLowerCase()}</a><button class="btn-secondary" id="modal-back">Back to portfolio</button></div></div></div></div>`;$('#modal-backdrop').onclick=e=>{if(e.target.id==='modal-backdrop')closeModal()};$('#modal-close').onclick=closeModal;$('#modal-back').onclick=closeModal;$('#modal-order').onclick=closeModal}
function closeModal(){state.active=null;$('#modal-root').innerHTML='';document.body.style.overflow=''}
function observeReveal(){const els=$$('.reveal');if(!('IntersectionObserver' in window)){els.forEach(e=>e.classList.add('is-visible'));return}const io=new IntersectionObserver(entries=>entries.forEach(en=>{if(en.isIntersecting){en.target.classList.add('is-visible');io.unobserve(en.target)}}),{threshold:.12});els.forEach(e=>{if(!e.classList.contains('is-visible'))io.observe(e)})}
function toast(msg){const root=$('#toast-root'),el=document.createElement('div');el.className='toast';el.textContent=msg;root.appendChild(el);setTimeout(()=>el.remove(),4200)}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.active)closeModal()});
render();
